// AIR-91 - arma y sanitiza el cuerpo del error desde el Error Trigger.
// Estructura del Error Trigger: { workflow:{id,name}, execution:{id,url,error,lastNodeExecuted,mode}, ... }
const j = $json || {};
const wf = j.workflow || {};
const ex = j.execution || {};
const err = ex.error || j.error || {};

// Nombre del ultimo nodo que se ejecuto (el que probablemente fallo).
const lastNode = ex.lastNodeExecuted || (err.node && err.node.name) || (typeof err.node === 'string' ? err.node : '') || 'unknown';

// Sanitiza: quita control chars (incl. \x7F), colapsa espacios y trunca.
function sanitize(s, max) {
  if (s == null) return '';
  let out = String(s).replace(/[\u0000-\u001F\u007F]/g, ' ').replace(/\s+/g, ' ').trim();
  if (out.length > max) out = out.substring(0, max);
  return out;
}

const rawMessage = err.message || err.description || (typeof err === 'string' ? err : '') || 'sin mensaje de error';
const mensaje = sanitize(rawMessage, 1500);
const workflowName = sanitize(wf.name || 'desconocido', 200);
const executionId = sanitize(ex.id || j.id || '', 64);
const nodoFallido = sanitize(lastNode, 200);

// error_mensaje en sync_log es texto: guardamos un JSON serializado legible.
const errorMensaje = sanitize(JSON.stringify({
  workflow: workflowName,
  execution_id: executionId,
  node: nodoFallido,
  message: mensaje
}), 2000);

// Slack URL desde env (puede estar vacia -> no se notifica).
let slackUrl = '';
try { slackUrl = ($env && $env.SLACK_WEBHOOK_URL) ? String($env.SLACK_WEBHOOK_URL).trim() : ''; } catch (e) { slackUrl = ''; }
const hasSlack = /^https?:\/\//i.test(slackUrl);

const slackText = sanitize('n8n workflow error :rotating_light:\nWorkflow: ' + workflowName + '\nNodo: ' + nodoFallido + '\nExecution: ' + executionId + '\nError: ' + mensaje, 1900);

return [{ json: {
  workflow_name: workflowName,
  execution_id: executionId,
  nodo_fallido: nodoFallido,
  mensaje: mensaje,
  error_mensaje: errorMensaje,
  slack_url: slackUrl,
  has_slack: hasSlack,
  slack_text: slackText
}}];
